function EJ8(){var dc={};dc.version='1.2.0';dc._mods={};dc._regQueue=[];dc._unregQueue=[];dc._chatQueue=[];dc._sendQueue=[];dc._togQueue=[];dc._enableQueue=[];dc._disableQueue=[];dc._settingQueue=[];dc._cmdQueue=[];dc._listeners={};dc._playerState=null;dc._worldState=null;dc._serverInfo=null;dc.registerMod=function(cfg){if(!cfg||!cfg.name){$rt_globals.console.warn('[DC] registerMod: name required');return;}dc._mods[cfg.name]=cfg;cfg._toggled=false;cfg._settings=cfg.settings||[];dc._regQueue.push(cfg.name);return cfg;};dc.unregisterMod
=function(name){if(dc._mods[name]){dc._unregQueue.push(''+name);delete dc._mods[name];}};dc.chat=function(msg){dc._chatQueue.push(''+msg);};dc.sendChat=function(msg){dc._sendQueue.push(''+msg);};dc.toggleMod=function(name){dc._togQueue.push(''+name);};dc.enableMod=function(name){dc._enableQueue.push(''+name);};dc.disableMod=function(name){dc._disableQueue.push(''+name);};dc.isEnabled=function(name){var m=dc._mods[name];return m?!!m._toggled:false;};dc.getPlayer=function(){return dc._playerState;};dc.getWorld
=function(){return dc._worldState;};dc.getServer=function(){return dc._serverInfo;};dc.getMods=function(){var names=[];for(var k in dc._mods)names.push(k);return names;};dc.getModInfo=function(name){var m=dc._mods[name];if(!m)return null;return {name:m.name,description:m.description||'',category:m.category||'PLAYER',isCheat:!!m.isCheat,enabled:!!m._toggled,settings:m._settings||[]};};dc.setModSetting=function(mod,setting,value){dc._settingQueue.push($rt_globals.JSON.stringify({mod:mod,setting:setting,value:
value}));};dc.getModSetting=function(mod,setting){var m=dc._mods[mod];if(!m)return null;for(var i=0;i<m._settings.length;i++){if(m._settings[i].name===setting)return m._settings[i].value;}return null;};dc.sendCommand=function(cmd){var c=cmd.startsWith('/')?cmd:'/'+cmd;dc._sendQueue.push(c);};dc.on=function(ev,cb){if(!dc._listeners[ev])dc._listeners[ev]=[];dc._listeners[ev].push(cb);};dc.off=function(ev,cb){if(!dc._listeners[ev])return;dc._listeners[ev]=dc._listeners[ev].filter(function(f){return f!==cb;});};dc._fire
=function(ev,data){var ls=dc._listeners[ev];if(!ls)return;for(var i=0;i<ls.length;i++){try {ls[i](data);}catch(e){$rt_globals.console.error('[DC] Event handler error ('+ev+'):',e);}}};dc.log=function(m){$rt_globals.console.log('[DC] '+m);};dc.warn=function(m){$rt_globals.console.warn('[DC] '+m);};dc.error=function(m){$rt_globals.console.error('[DC] '+m);};dc.help=function(){var lines=['=== DeathClient JS API v'+dc.version+' ===','','REGISTRATION','  registerMod(cfg)         Register a mod. cfg: {name, description,',
'                             category, isCheat, onEnable, onDisable,','                             onUpdate, onRender2D, settings:[...]}','  unregisterMod(name)      Remove a JS mod at runtime','','CHAT & COMMANDS','  chat(msg)                Show msg in local chat only','  sendChat(msg)            Send chat to server','  sendCommand(cmd)         Send /command to server','','MOD CONTROL','  toggleMod(name)          Toggle any mod by name','  enableMod(name)          Enable a mod','  disableMod(name)         Disable a mod',
'  isEnabled(name)          Returns boolean','  getMods()                Returns array of all mod names','  getModInfo(name)         Returns {name,description,category,isCheat,enabled,settings}','  setModSetting(mod,s,val) Change a mod setting','  getModSetting(mod,s)     Read a JS mod setting','','WORLD DATA','  getPlayer()    {x,y,z,yaw,pitch,health,maxHealth,food,saturation,','                  onGround,sprinting,sneaking,motionX,motionY,motionZ,','                  eyeHeight,dimension,gamemode,xp,level}',
'  getWorld()     {time,timeOfDay,isRaining,thundering,difficulty,dimension}','  getServer()    {ip,port,ping}','','EVENTS  (dc.on / dc.off)','  tick            fired every game tick','  render2d        fired every rendered frame','  chat_receive    fired when a chat message arrives','  mod_enable      fired when any mod enables {name}','  mod_disable     fired when any mod disables {name}','','FILES','  openFilePicker(accept)   Open file dialog (.js default)','','EXAMPLE','  DeathClient.registerMod({','    name: "MyMod", category: "MOVEMENT", isCheat: false,',
'    settings: [{name:"Speed",type:"number",value:1.5,min:0.5,max:5}],','    onEnable:  function() { DeathClient.chat("on!"); },','    onDisable: function() { DeathClient.chat("off!"); },','    onUpdate:  function() { var p=DeathClient.getPlayer(); }','  });'];$rt_globals.console.log(lines.join('\n'));};$rt_globals.window.DeathClient=dc;$rt_globals.console.log('[DeathClient] JS API v'+dc.version+' ready. Run DeathClient.help() for docs.');}
